/* test_layout.c: hold the C ring to the committed layout vectors.
 *
 * vectors/layout_vectors.tsv is generated by
 * vectors/gen_layout_vectors.py, which declares every region, ring, attach,
 * lease-view and AMOD layout from the specification, independently of any
 * implementation. This test checks the C structures and constants against it
 * in both directions: every row must match a C value, and every C value listed
 * here must have a row. The Go (go/ring/layout_test.go) and Rust
 * (rust/src/layout.rs) clients are held to the same table, so the
 * three agree through it rather than by reading each other.
 *
 * Offsets come from offsetof on the shared structures. The AMOD envelope has no
 * C struct on the wire, so its offsets are checked by encoding a message with
 * distinct field values and finding each value at the table's offset.
 */
#include <errno.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <ouroboros/attach.h>
#include <ouroboros/region.h>
#include <ouroboros/ring.h>
#include <ouroboros/telemetry.h>
#include <ouroboros/wire.h>
#include <ouroboros/module_protocol.h>

#include "region_internal.h"

#ifndef OURO_VECTOR_DIR
#define OURO_VECTOR_DIR "vectors"
#endif
#define LAYOUT_PATH OURO_VECTOR_DIR "/layout_vectors.tsv"

static int failures;

static void fail(const char *what, const char *name)
{
   fprintf(stderr, "FAIL: %s: %s\n", what, name);
   failures++;
}

typedef struct
{
   const char *name;
   unsigned long long value;
   int seen;
} entry_t;

/* AMOD field offsets, found from the C codec's behaviour rather than read from
 * a struct (the envelope has none on the wire). A field the encoder takes from
 * the message is located by encoding two messages that differ only in it and
 * finding the first byte that differs. A field the encoder fixes (magic,
 * version, header_len) or that must be zero (flags) is located by corrupting
 * one byte at a time and finding the first offset whose corruption the decoder
 * reports with that field's own error. */
static const ouro_module_message_t amod_base = {.operation = OURO_MODULE_OP_RESULT,
                                                 .status = OURO_MODULE_STATUS_OK,
                                                 .stage_id = 1,
                                                 .flags = 0,
                                                 .body_len = 0,
                                                 .deadline_ns = 0,
                                                 .trace_id = 0};

static unsigned long long amod_varied(void (*vary)(ouro_module_message_t *))
{
   uint8_t a[OURO_MODULE_MESSAGE_HEADER_LEN], b[OURO_MODULE_MESSAGE_HEADER_LEN];
   ouro_module_message_t m = amod_base;
   if (ouro_module_message_encode(&m, a, sizeof a) != sizeof a)
      return ~0ull;
   vary(&m);
   if (ouro_module_message_encode(&m, b, sizeof b) != sizeof b)
      return ~0ull;
   for (size_t i = 0; i < sizeof a; i++)
      if (a[i] != b[i])
         return i;
   return ~0ull;
}

static unsigned long long amod_refused(ouro_module_message_result_t why)
{
   uint8_t good[OURO_MODULE_MESSAGE_HEADER_LEN];
   ouro_module_message_t m = amod_base;
   if (ouro_module_message_encode(&m, good, sizeof good) != sizeof good)
      return ~0ull;
   for (size_t i = 0; i < sizeof good; i++)
   {
      uint8_t b[sizeof good];
      memcpy(b, good, sizeof b);
      b[i] ^= 0x80;
      ouro_module_message_t out;
      if (ouro_module_message_decode(b, sizeof b, &out) == why)
         return i;
   }
   return ~0ull;
}

static void v_op(ouro_module_message_t *m)
{
   m->operation = OURO_MODULE_OP_INVOKE;
}
static void v_status(ouro_module_message_t *m)
{
   m->status = OURO_MODULE_STATUS_INTERNAL;
}
static void v_stage(ouro_module_message_t *m)
{
   m->stage_id = 2;
}
static void v_body(ouro_module_message_t *m)
{
   m->body_len = 1;
}
static void v_deadline(ouro_module_message_t *m)
{
   m->deadline_ns = 1;
}
static void v_trace(ouro_module_message_t *m)
{
   m->trace_id = 1;
}

int main(void)
{
#define E(n, v) {n, (unsigned long long)(v), 0}
   entry_t want[] = {
       E("version.spec", OURO_SPEC_VERSION),
       E("version.layout", OURO_LAYOUT_VERSION),
       E("version.wire", OURO_WIRE_VERSION),
       E("version.amod", OURO_MODULE_MESSAGE_VERSION),
       E("frame.size", OURO_WIRE_HDR_LEN),
       E("frame.magic", OURO_WIRE_MAGIC),

       E("kind.attach_request", OURO_KIND_ATTACH_REQUEST),
       E("kind.attach_reply", OURO_KIND_ATTACH_REPLY),
       E("kind.error", OURO_KIND_ERROR),
       E("kind.capability_absent", OURO_KIND_CAPABILITY_ABSENT),
       E("kind.overflow", OURO_KIND_OVERFLOW),
       E("kind.producer_reaped", OURO_KIND_PRODUCER_REAPED),
       E("kind.epoch_change", OURO_KIND_EPOCH_CHANGE),
       E("kind.capability_denied", OURO_KIND_CAPABILITY_DENIED),
       E("kind.lease_release", OURO_KIND_LEASE_RELEASE),
       E("kind.module_base", OURO_KIND_MODULE_BASE),

       E("control.magic", OURO_CONTROL_MAGIC),
       E("control.size", sizeof(ouro_control_t)),
       E("control.off.magic", offsetof(ouro_control_t, magic)),
       E("control.off.spec_version", offsetof(ouro_control_t, spec_version)),
       E("control.off.layout_version", offsetof(ouro_control_t, layout_version)),
       E("control.off.flags", offsetof(ouro_control_t, flags)),
       E("control.off.slot_size", offsetof(ouro_control_t, slot_size)),
       E("control.off.inline_budget", offsetof(ouro_control_t, inline_budget)),
       E("control.off.queue_capacity", offsetof(ouro_control_t, queue_capacity)),
       E("control.off.lease_view_slots", offsetof(ouro_control_t, lease_view_slots)),
       E("control.off.arena_size", offsetof(ouro_control_t, arena_size)),
       E("control.off.host_epoch", offsetof(ouro_control_t, host_epoch)),
       E("control.off.host_heartbeat", offsetof(ouro_control_t, host_heartbeat)),
       E("control.off.lease_view_off", offsetof(ouro_control_t, lease_view_off)),
       E("control.off.host_waiting", offsetof(ouro_control_t, host_waiting)),
       E("control.off.reserved2", offsetof(ouro_control_t, reserved2)),
       E("control.off.reserved1", offsetof(ouro_control_t, reserved1)),
       E("control.flag.lease_view", OURO_CONTROL_F_LEASE_VIEW),
       E("control.flag.doorbell", OURO_CONTROL_F_DOORBELL),

       E("lease_view.slots", OURO_LEASE_VIEW_SLOTS),
       E("lease_view.entry.size", sizeof(ouro_lease_view_t)),
       E("lease_view.entry.off.generation", offsetof(ouro_lease_view_t, generation)),
       E("lease_view.entry.off.len", offsetof(ouro_lease_view_t, len)),
       E("lease_view.entry.off.offset", offsetof(ouro_lease_view_t, offset)),
       E("lease_view.region_bytes", ouro_control_bytes()),

       E("qpair.magic", OURO_QPAIR_MAGIC),
       E("qpair.size", sizeof(ouro_qpair_hdr_t)),
       E("qpair.off.magic", offsetof(ouro_qpair_hdr_t, magic)),
       E("qpair.off.slot_size", offsetof(ouro_qpair_hdr_t, slot_size)),
       E("qpair.off.capacity", offsetof(ouro_qpair_hdr_t, capacity)),
       E("qpair.off.data_credits", offsetof(ouro_qpair_hdr_t, data_credits)),
       E("qpair.off.control_credits", offsetof(ouro_qpair_hdr_t, control_credits)),
       E("qpair.off.control_lost", offsetof(ouro_qpair_hdr_t, control_lost)),
       E("qpair.off.inbound_off", offsetof(ouro_qpair_hdr_t, inbound_off)),
       E("qpair.off.outbound_off", offsetof(ouro_qpair_hdr_t, outbound_off)),
       E("qpair.off.client_heartbeat", offsetof(ouro_qpair_hdr_t, client_heartbeat)),
       E("qpair.off.client_waiting", offsetof(ouro_qpair_hdr_t, client_waiting)),
       E("qpair.off.reserved0", offsetof(ouro_qpair_hdr_t, reserved0)),
       E("qpair.off.reserved", offsetof(ouro_qpair_hdr_t, reserved)),
       E("qpair.ring_align", ouro_region_align64(1)),

       E("ring.magic", OURO_RING_MAGIC),
       E("ring.off.magic", offsetof(ouro_ring_shared_t, magic)),
       E("ring.off.slot_size", offsetof(ouro_ring_shared_t, slot_size)),
       E("ring.off.capacity", offsetof(ouro_ring_shared_t, capacity)),
       E("ring.off.mask", offsetof(ouro_ring_shared_t, mask)),
       E("ring.off.slots_off", offsetof(ouro_ring_shared_t, slots_off)),
       E("ring.off.head", offsetof(ouro_ring_shared_t, head)),
       E("ring.off.tail", offsetof(ouro_ring_shared_t, tail)),
       E("ring.size", offsetof(ouro_ring_shared_t, slots)),

       E("arena.magic", OURO_ARENA_MAGIC),
       E("arena.size", sizeof(ouro_arena_hdr_t)),
       E("arena.off.magic", offsetof(ouro_arena_hdr_t, magic)),
       E("arena.off.reserved", offsetof(ouro_arena_hdr_t, reserved)),
       E("arena.off.size", offsetof(ouro_arena_hdr_t, size)),

       E("attach_request.magic", OURO_ATTACH_REQ_MAGIC),
       E("attach_request.size", sizeof(ouro_attach_request_t)),
       E("attach_request.off.magic", offsetof(ouro_attach_request_t, magic)),
       E("attach_request.off.wire_version_min", offsetof(ouro_attach_request_t, wire_version_min)),
       E("attach_request.off.wire_version_max", offsetof(ouro_attach_request_t, wire_version_max)),
       E("attach_request.off.principal_class", offsetof(ouro_attach_request_t, principal_class)),
       E("attach_request.off.principal_ref", offsetof(ouro_attach_request_t, principal_ref)),
       E("attach_request.off.capabilities", offsetof(ouro_attach_request_t, capabilities)),
       E("attach_request.v0_size", OURO_ATTACH_REQ_V0_BYTES),
       E("attach.cap.doorbell", OURO_ATTACH_CAP_DOORBELL),
       E("attach.cap.process_liveness", OURO_ATTACH_CAP_PROCESS_LIVENESS),
       E("attach.cap.telemetry", OURO_ATTACH_CAP_TELEMETRY),
       E("attach_reply.magic", OURO_ATTACH_REPLY_MAGIC),
       E("attach_reply.size", sizeof(ouro_attach_reply_t)),
       E("attach_reply.off.magic", offsetof(ouro_attach_reply_t, magic)),
       E("attach_reply.off.status", offsetof(ouro_attach_reply_t, status)),
       E("attach_reply.off.handle_id", offsetof(ouro_attach_reply_t, handle_id)),
       E("attach_reply.off.wire_version", offsetof(ouro_attach_reply_t, wire_version)),
       E("attach_reply.off.slot_size", offsetof(ouro_attach_reply_t, slot_size)),
       E("attach_reply.off.inline_budget", offsetof(ouro_attach_reply_t, inline_budget)),
       E("attach_reply.off.queue_capacity", offsetof(ouro_attach_reply_t, queue_capacity)),
       E("attach_reply.off.capabilities", offsetof(ouro_attach_reply_t, capabilities)),
       E("attach_reply.off.arena_size", offsetof(ouro_attach_reply_t, arena_size)),
       E("attach_reply.off.host_epoch", offsetof(ouro_attach_reply_t, host_epoch)),
       E("attach_status.ok", OURO_ATTACH_OK),
       E("attach_status.denied_policy", OURO_ATTACH_DENIED_POLICY),
       E("attach_status.denied_version", OURO_ATTACH_DENIED_VERSION),
       E("attach_status.denied_noslot", OURO_ATTACH_DENIED_NOSLOT),
       E("attach_status.protocol", OURO_ATTACH_PROTOCOL),
       E("attach.descriptors", OURO_ATTACH_FDS),
       E("attach.fd.control", OURO_ATTACH_FD_CONTROL),
       E("attach.fd.arena", OURO_ATTACH_FD_ARENA),
       E("attach.fd.qpair", OURO_ATTACH_FD_QPAIR),
       E("attach.descriptors_doorbell", OURO_ATTACH_FDS_DOORBELL),
       E("attach.fd.host_doorbell", OURO_ATTACH_FD_HOST_DOORBELL),
       E("attach.fd.client_doorbell", OURO_ATTACH_FD_CLIENT_DOORBELL),
       E("attach.descriptors_telemetry", OURO_ATTACH_FDS_TELEMETRY),
       E("attach.fd.telemetry", OURO_ATTACH_FD_TELEMETRY),
       E("attach.fd.telemetry_doorbell", OURO_ATTACH_FD_TELEMETRY_BELL),

       E("telemetry.magic", OURO_TELEMETRY_MAGIC),
       E("telemetry.version", OURO_TELEMETRY_VERSION),
       E("telemetry.off.magic", offsetof(ouro_telemetry_region_t, magic)),
       E("telemetry.off.version", offsetof(ouro_telemetry_region_t, version)),
       E("telemetry.off.record_size", offsetof(ouro_telemetry_region_t, record_size)),
       E("telemetry.off.flags", offsetof(ouro_telemetry_region_t, flags)),
       E("telemetry.off.host_epoch", offsetof(ouro_telemetry_region_t, host_epoch)),
       E("telemetry.off.dropped", offsetof(ouro_telemetry_region_t, dropped)),
       E("telemetry.off.drain_interval_ns", offsetof(ouro_telemetry_region_t, drain_interval_ns)),
       E("telemetry.off.idle_after_ns", offsetof(ouro_telemetry_region_t, idle_after_ns)),
       E("telemetry.off.consumer_waiting", offsetof(ouro_telemetry_region_t, consumer_waiting)),
       E("telemetry.off.ring", OURO_TELEMETRY_REGION_OFF_RING),
       E("telemetry_record.off.type", OURO_TELEMETRY_OFF_TYPE),
       E("telemetry_record.off.flags", OURO_TELEMETRY_OFF_FLAGS),
       E("telemetry_record.off.realtime_ns", OURO_TELEMETRY_OFF_REALTIME_NS),
       E("telemetry_record.off.lost", OURO_TELEMETRY_OFF_LOST),
       E("telemetry_record.off.reserved", OURO_TELEMETRY_OFF_RESERVED),
       E("telemetry_record.off.frame", OURO_TELEMETRY_OFF_FRAME),
       E("telemetry_record.off.reserved_tail", OURO_TELEMETRY_OFF_RESERVED_TAIL),
       E("telemetry_record.size", OURO_TELEMETRY_RECORD_LEN),
       E("telemetry_record.type.event", OURO_TELEMETRY_RECORD_EVENT),
       E("telemetry_record.type.gap", OURO_TELEMETRY_RECORD_GAP),

       E("lease_release.size", OURO_LEASE_RELEASE_LEN),
       E("lease_release.off.lease_id", OURO_LEASE_RELEASE_OFF_LEASE),
       E("lease_release.off.generation", OURO_LEASE_RELEASE_OFF_GENERATION),
       E("overflow.size", OURO_OVERFLOW_LEN),
       E("overflow.off.shed_seq", OURO_OVERFLOW_OFF_SHED_SEQ),
       E("overflow.off.shed_kind", OURO_OVERFLOW_OFF_SHED_KIND),
       E("overflow.off.dst_slot", OURO_OVERFLOW_OFF_DST_SLOT),

       E("amod.magic", OURO_MODULE_MESSAGE_MAGIC),
       E("amod.size", OURO_MODULE_MESSAGE_HEADER_LEN),
       E("amod.off.magic", amod_refused(OURO_MODULE_MESSAGE_ERR_MAGIC)),
       E("amod.off.version", amod_refused(OURO_MODULE_MESSAGE_ERR_VERSION)),
       E("amod.off.header_len", amod_refused(OURO_MODULE_MESSAGE_ERR_HEADER)),
       E("amod.off.operation", amod_varied(v_op)),
       E("amod.off.status", amod_varied(v_status)),
       E("amod.off.stage_id", amod_varied(v_stage)),
       E("amod.off.flags", amod_refused(OURO_MODULE_MESSAGE_ERR_FLAGS)),
       E("amod.off.body_len", amod_varied(v_body)),
       E("amod.off.deadline_ns", amod_varied(v_deadline)),
       E("amod.off.trace_id", amod_varied(v_trace)),
       E("amod.max_body", OURO_MODULE_MESSAGE_MAX_BODY),
       E("amod.op.invoke", OURO_MODULE_OP_INVOKE),
       E("amod.op.result", OURO_MODULE_OP_RESULT),
       E("amod.status.ok", OURO_MODULE_STATUS_OK),
       E("amod.status.capability_absent", OURO_MODULE_STATUS_CAPABILITY_ABSENT),
       E("amod.status.cancelled", OURO_MODULE_STATUS_CANCELLED),
       E("amod.status.deadline_exceeded", OURO_MODULE_STATUS_DEADLINE_EXCEEDED),
       E("amod.status.invalid_request", OURO_MODULE_STATUS_INVALID_REQUEST),
       E("amod.status.internal", OURO_MODULE_STATUS_INTERNAL),
   };
#undef E
   const size_t nwant = sizeof want / sizeof want[0];

   FILE *f = fopen(LAYOUT_PATH, "r");
   if (!f)
   {
      fprintf(stderr, "FAIL: open %s: %s\n", LAYOUT_PATH, strerror(errno));
      return 1;
   }
   char line[512];
   size_t rows = 0;
   while (fgets(line, sizeof line, f))
   {
      if (line[0] == '#' || line[0] == '\n')
         continue;
      char *tab = strchr(line, '\t');
      if (!tab)
      {
         fail("malformed row", line);
         continue;
      }
      *tab = '\0';
      char *end = NULL;
      unsigned long long v = strtoull(tab + 1, &end, 0);
      if (end == tab + 1 || (*end != '\n' && *end != '\0'))
      {
         fail("malformed value", line);
         continue;
      }
      rows++;
      size_t i = 0;
      for (; i < nwant; i++)
         if (strcmp(want[i].name, line) == 0)
            break;
      if (i == nwant)
      {
         fail("row has no C counterpart (add one to test_layout.c)", line);
         continue;
      }
      if (want[i].seen)
         fail("duplicate row", line);
      want[i].seen = 1;
      if (want[i].value != v)
      {
         fprintf(stderr, "FAIL: %s: table %llu, C %llu\n", line, v, want[i].value);
         failures++;
      }
   }
   fclose(f);
   for (size_t i = 0; i < nwant; i++)
      if (!want[i].seen)
         fail("C value missing from the table", want[i].name);
   if (rows == 0)
      fail("no rows", LAYOUT_PATH);
   if (failures)
   {
      fprintf(stderr, "test_layout: %d failure(s)\n", failures);
      return 1;
   }
   printf("test_layout: OK (%zu rows agree with the C layout)\n", rows);
   return 0;
}
